current_owl:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/UNEDIFACT-Invoice-Ontology>
    a owl:Ontology ;
    rdfs:label "UN/EDIFACT Invoice Ontology" ;
    rdfs:comment "An ontology for representing UN/EDIFACT invoice messages, organizational roles, and message structure, aligned with EN 16931-1 and P2P-O." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A digital business document, e.g., an invoice, within an interchange envelope." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An invoice message (e.g., INVOIC) in EDIFACT." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment in an EDIFACT message (e.g., BGM, NAD)." .

:InvoiceHeaderSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Invoice Header Section" ;
    rdfs:comment "Header section of an invoice, including dates and reference numbers." .

:InvoiceDetailSection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Invoice Detail Section" ;
    rdfs:comment "Detail section listing invoice line items." .

:InvoiceSummarySection a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "Invoice Summary Section" ;
    rdfs:comment "Summary section providing totals and tax amounts." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite element." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An entity involved in the invoice process, such as buyer or delivery party." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization within the invoice context (e.g., Buyer, Delivery Party)." .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "A pivot class linking an organization, a role, and the invoice context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier such as a Global Location Number (GLN)." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service sold in the invoice." .

:LineItem a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item in the invoice detail section." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A generic price class for invoice amounts and line item prices." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasNetPrice ; owl:someValuesFrom :NetPrice ] , [ a owl:Restriction ; owl:onProperty :hasInvoiceAmount ; owl:someValuesFrom :InvoiceAmount ] .

:NetPrice a owl:Class ;
    rdfs:subClassOf :Price ;
    rdfs:label "Net Price" ;
    rdfs:comment "The net price of an item in a line item." .

:InvoiceAmount a owl:Class ;
    rdfs:subClassOf :Price ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total invoice amount." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

#################################################################
# Object Properties with Inverses
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Links a message to its containing envelope." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its segments." ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of" ;
    rdfs:comment "Links a segment to its message." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "is composite element of" ;
    rdfs:comment "Links a composite data element to its segment." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to its simple data elements." ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Links a simple data element to its composite element." .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an invoice message to an involved organization." ;
    owl:inverseOf :isInvolvedInMessage .

:isInvolvedInMessage a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is involved in message" ;
    rdfs:comment "Links an organization to the invoice message it is involved in." .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an invoice message to a role assignment (organization + role)." ;
    owl:inverseOf :isRoleAssignmentOfMessage .

:isRoleAssignmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is role assignment of message" ;
    rdfs:comment "Links a role assignment to its invoice message." .

:assignedRole a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "assigned role" ;
    rdfs:comment "Links a role assignment to an agent role (e.g., Buyer, Delivery Party)." ;
    owl:inverseOf :isRoleAssignedToAssignment .

:isRoleAssignedToAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "is role assigned to assignment" ;
    rdfs:comment "Links an agent role to its role assignment." .

:assignedOrganization a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "assigned organization" ;
    rdfs:comment "Links a role assignment to an organization." ;
    owl:inverseOf :isOrganizationAssignedToAssignment .

:isOrganizationAssignedToAssignment a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "is organization assigned to assignment" ;
    rdfs:comment "Links an organization to its role assignment." .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of organization" ;
    rdfs:comment "Links an address to its organization." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifier (e.g., GLN)." ;
    owl:inverseOf :isIdentifierOfOrganization .

:isIdentifierOfOrganization a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "is identifier of organization" ;
    rdfs:comment "Links an identifier to its organization." .

:buyerRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "buyer role assignment" ;
    rdfs:comment "Links an invoice message to its buyer role assignment." ;
    owl:inverseOf :isBuyerRoleAssignmentOfMessage .

:isBuyerRoleAssignmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is buyer role assignment of message" ;
    rdfs:comment "Links a buyer role assignment to its invoice message." .

:deliveryPartyRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment ;
    rdfs:label "delivery party role assignment" ;
    rdfs:comment "Links an invoice message to its delivery party role assignment." ;
    owl:inverseOf :isDeliveryPartyRoleAssignmentOfMessage .

:isDeliveryPartyRoleAssignmentOfMessage a owl:ObjectProperty ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is delivery party role assignment of message" ;
    rdfs:comment "Links a delivery party role assignment to its invoice message." .

:describesItem a owl:ObjectProperty ;
    rdfs:domain :InvoiceDetailSection ;
    rdfs:range :LineItem ;
    rdfs:label "describes item" ;
    rdfs:comment "Links the detail section to its line items." ;
    owl:inverseOf :isDescribedByDetailSection .

:isDescribedByDetailSection a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :InvoiceDetailSection ;
    rdfs:label "is described by detail section" ;
    rdfs:comment "Links a line item to its detail section." .

:itemOf a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    rdfs:label "item of" ;
    rdfs:comment "Links a line item to the described item." ;
    owl:inverseOf :isItemDescribedByLineItem .

:isItemDescribedByLineItem a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    rdfs:label "is item described by line item" ;
    rdfs:comment "Links an item to its describing line item." .

:hasNetPrice a owl:ObjectProperty ;
    rdfs:domain :LineItem ;
    rdfs:range :NetPrice ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a line item to its net price." ;
    owl:inverseOf :isNetPriceOfLineItem .

:isNetPriceOfLineItem a owl:ObjectProperty ;
    rdfs:domain :NetPrice ;
    rdfs:range :LineItem ;
    rdfs:label "is net price of line item" ;
    rdfs:comment "Links a net price to its line item." .

:hasInvoiceAmount a owl:ObjectProperty ;
    rdfs:domain :InvoiceSummarySection ;
    rdfs:range :InvoiceAmount ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links the summary section to the total invoice amount." ;
    owl:inverseOf :isInvoiceAmountOfSummarySection .

:isInvoiceAmountOfSummarySection a owl:ObjectProperty ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range :InvoiceSummarySection ;
    rdfs:label "is invoice amount of summary section" ;
    rdfs:comment "Links an invoice amount to its summary section." .

:relatesToBusinessProcess a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "relates to business process" ;
    rdfs:comment "Links the invoice message to a business process." ;
    owl:inverseOf :isBusinessProcessRelatedToMessage .

:isBusinessProcessRelatedToMessage a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is business process related to message" ;
    rdfs:comment "Links a business process to its related invoice message." .

#################################################################
# Data Properties
#################################################################

:hasInvoiceNumber a owl:DatatypeProperty ;
    rdfs:domain :InvoiceHeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number." .

:hasDate a owl:DatatypeProperty ;
    rdfs:domain :InvoiceHeaderSection ;
    rdfs:range xsd:dateTime ;
    rdfs:label "has date" ;
    rdfs:comment "The date of the invoice." .

:hasReferenceNumber a owl:DatatypeProperty ;
    rdfs:domain :InvoiceHeaderSection ;
    rdfs:range xsd:string ;
    rdfs:label "has reference number" ;
    rdfs:comment "The reference number in the invoice header." .

:hasOrganizationName a owl:DatatypeProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has organization name" ;
    rdfs:comment "The name of the organization." .

:hasAddressLine a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "has address line" ;
    rdfs:comment "The address line of an address." .

:hasPostalCode a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "has postal code" ;
    rdfs:comment "The postal code of an address." .

:hasCity a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "has city" ;
    rdfs:comment "The city of an address." .

:hasCountryCode a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "has country code" ;
    rdfs:comment "The country code of an address." .

:hasGLN a owl:DatatypeProperty ;
    rdfs:domain :Identifier ;
    rdfs:range xsd:string ;
    rdfs:label "has GLN" ;
    rdfs:comment "The Global Location Number (GLN) identifier." .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal ;
    rdfs:label "has quantity" ;
    rdfs:comment "The quantity of the item in a line item." .

:hasNetPriceValue a owl:DatatypeProperty ;
    rdfs:domain :NetPrice ;
    rdfs:range xsd:decimal ;
    rdfs:label "has net price value" ;
    rdfs:comment "The numeric value of the net price." .

:hasInvoiceAmountValue a owl:DatatypeProperty ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range xsd:decimal ;
    rdfs:label "has invoice amount value" ;
    rdfs:comment "The numeric value of the invoice amount." .

:hasTaxAmount a owl:DatatypeProperty ;
    rdfs:domain :InvoiceSummarySection ;
    rdfs:range xsd:decimal ;
    rdfs:label "has tax amount" ;
    rdfs:comment "The total tax amount in the invoice summary section." .

#################################################################
# Class Disjointness/Unions
#################################################################

:InvoiceHeaderSection owl:disjointWith :InvoiceDetailSection , :InvoiceSummarySection .
:InvoiceDetailSection owl:disjointWith :InvoiceSummarySection .

:Item owl:disjointWith :Organization .

:Segment owl:disjointUnionOf ( :InvoiceHeaderSection :InvoiceDetailSection :InvoiceSummarySection ) .
